-- 活动列表查询优化
CREATE INDEX idx_activity_category_status
  ON "Activity"(category, status);
CREATE INDEX idx_activity_date
  ON "Activity"(date) WHERE status IN ('ENROLLING', 'FULL');
CREATE INDEX idx_activity_location
  ON "Activity"(latitude, longitude);

-- 会话消息查询
CREATE INDEX idx_message_conv_time
  ON "Message"(conversation_id, created_at DESC);

-- 用户收藏
CREATE INDEX idx_favorite_user
  ON "Favorite"(user_id);
